	double value;
	status = napi_get_value_double( env, argv[ 0 ], &value );
	assert( status == napi_ok );

	stdlib_float16_t result;
	result = stdlib_base_float32_to_float16( (float)value );

	napi_value v;
	status = napi_create_uint32( env, stdlib_float16_to_bits( result ), &v );
	assert( status == napi_ok );

